changeSet.sql:
create table data.llm_advice_source_response (
  llm_advice_id int4 null constraint llm_advice_response_llm_advice references data.llm_advice(id) on delete cascade,
  ts_db         timestamp default localtimestamp not null,
  llm_request   text,
  llm_response  text
);
create index idx_llm_advice_source_response_advice on data.llm_advice_source_response(llm_advice_id);

create trigger trg_dict_changed_llm_prompts_futures_metrics
after insert or update or delete on data.llm_prompts_futures_metrics
for each statement execute function data.fn_dict_changed_notify();
